message.content:
{
  "candidate_edge_types": [
    {
      "name": "ATTEMPTS_TO_REPAIR_FAILURE",
      "definition": "A subsequent agent action attempts to resolve a failure or incompatibility identified during an earlier execution step.",
      "source_description": "An earlier observed execution failure or environment incompatibility.",
      "target_description": "A subsequent agent action intended to resolve that failure or incompatibility."
    },
    {
      "name": "VERIFIES_PRIOR_RESULT_STATE",
      "definition": "The agent performs a separate check to determine whether an earlier action or produced artifact reached the expected state, content, or format.",
      "source_description": "An earlier action or produced result whose success or content is not yet confirmed.",
      "target_description": "A subsequent verification step that inspects the outcome of that earlier action or result."
    },
    {
      "name": "RESOLVES_AMBIGUITY_IN_PRIOR_RESULT",
      "definition": "A subsequent analytical step is performed to disambiguate conflicting, ambiguous, or unexpected outcomes produced by an earlier result.",
      "source_description": "An earlier result that presents conflicting, ambiguous, or constraint-violating outcomes.",
      "target_description": "A subsequent analytical or diagnostic step intended to disambiguate or investigate those outcomes."
    },
    {
      "name": "SELECTS_CANDIDATE_BASED_ON_EVALUATION",
      "definition": "The agent selects one candidate among several alternatives based on comparative evaluation evidence produced during earlier steps.",
      "source_description": "Comparative evaluation evidence, such as scores or test outcomes, for competing candidates.",
      "target_description": "The selected decision, configuration, or structure chosen on the basis of that evidence."
    },
    {
      "name": "USES_PRIOR_RESULT_AS_INPUT",
      "definition": "A subsequent agent operation consumes a result produced or confirmed by an earlier action as an input.",
      "source_description": "A prior execution result, such as an available tool, a determined structure, or a computed value.",
      "target_description": "A subsequent operation that uses that prior result as an input."
    },
    {
      "name": "RESPONDS_TO_CONFIRMATION_PROMPT",
      "definition": "In response to a system or tool prompt requesting confirmation before a consequential action is finalized, the agent re-issues or affirms the previously attempted action.",
      "source_description": "A system or tool prompt requesting confirmation of an attempted consequential action.",
      "target_description": "The agent's confirmation action re-affirming the earlier attempted action."
    }
  ]
}

